insert into jj_collect.catalog(id,data) values('nu-086','{"id": "nu-086", "number": 86, "name_es": "El planeta que imaginamos", "name_en": "The Planet We Imagine", "character": "duo", "theme": "fantasia", "rarity": 3, "sell": 220, "scrap": 35, "craft": 200, "dedication_es": "Nuestro rincón favorito puede empezar con una idea compartida y un poco de cariño.", "dedication_en": "Our favorite little place can begin with a shared idea and a little care.", "art": 25, "collection": "tercer-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-087','{"id": "nu-087", "number": 87, "name_es": "Arena de estrellas", "name_en": "Stardust in the Hourglass", "character": "duo", "theme": "fantasia", "rarity": 3, "sell": 220, "scrap": 35, "craft": 200, "dedication_es": "No quiero contar los minutos para exigirte más, sino agradecer los que compartimos.", "dedication_en": "I do not want to count minutes to ask for more, but to appreciate the ones we share.", "art": 26, "collection": "tercer-universo"}'::jsonb) on conflict(id) do nothing;
